  /// Returns a copy with [overrides] applied.
  ///
  /// Every key must be in [names] and every value must have the
  /// token's type, otherwise this throws.
  CsDensityModeTokens copyWithMap(Map<String, Object> overrides) {
    if (overrides.isEmpty) return this;
    for (final key in overrides.keys) {
      if (!names.contains(key)) {
        throw ArgumentError.value(
          key,
          'overrides',
          'Not in CsDensityModeTokens',
        );
      }
    }
    return CsDensityModeTokens(
      sizeCalendarGridWidth:
          (overrides['sizeCalendarGridWidth'] ?? sizeCalendarGridWidth)
              as double,
      sizeControl: (overrides['sizeControl'] ?? sizeControl) as double,
      sizeIconBig: (overrides['sizeIconBig'] ?? sizeIconBig) as double,
      sizeIconLarge: (overrides['sizeIconLarge'] ?? sizeIconLarge) as double,
      sizeIconMedium: (overrides['sizeIconMedium'] ?? sizeIconMedium) as double,
      sizeIconNormal: (overrides['sizeIconNormal'] ?? sizeIconNormal) as double,
      sizeTableSelectionHorizontal:
          (overrides['sizeTableSelectionHorizontal'] ??
                  sizeTableSelectionHorizontal)
              as double,
      sizeVerticalInput:
          (overrides['sizeVerticalInput'] ?? sizeVerticalInput) as double,
      sizeVerticalPanelIconOffset:
          (overrides['sizeVerticalPanelIconOffset'] ??
                  sizeVerticalPanelIconOffset)
              as double,
      sizeSideNavigationItemHeight:
          (overrides['sizeSideNavigationItemHeight'] ??
                  sizeSideNavigationItemHeight)
              as double,
      sizeSideNavigationItemCollapsed:
          (overrides['sizeSideNavigationItemCollapsed'] ??
                  sizeSideNavigationItemCollapsed)
              as double,
      sizeSideNavigationCollapsedWidth:
          (overrides['sizeSideNavigationCollapsedWidth'] ??
                  sizeSideNavigationCollapsedWidth)
              as double,
      spaceAlertActionLeft:
          (overrides['spaceAlertActionLeft'] ?? spaceAlertActionLeft) as double,
      spaceAlertHorizontal:
          (overrides['spaceAlertHorizontal'] ?? spaceAlertHorizontal) as double,
      spaceAlertMessageRight:
          (overrides['spaceAlertMessageRight'] ?? spaceAlertMessageRight)
              as double,
      spaceAlertVertical:
          (overrides['spaceAlertVertical'] ?? spaceAlertVertical) as double,
      spaceButtonFocusOutlineGutter:
